<section class="settings-group"><x-section-heading tag="h3" icon="receipt" tone="info">Print layout</x-section-heading><x-setting-select name="width" label="Receipt paper width" :value="$values['width']" :options="[58=>'58 mm',80=>'80 mm']" /><x-setting-select name="copies" label="Default receipt copies" :value="$values['copies']" :options="[1=>'1 copy',2=>'2 copies',3=>'3 copies']" /><x-setting-toggle name="show_logo" label="Show shop logo" :checked="$values['show_logo']" /><x-input id="receipt-footer" name="values[footer]" label="Receipt footer" :value="old('values.footer',$values['footer'])" maxlength="200" /><p class="measure-note">Keep the message short for thermal paper.</p><input type="hidden" name="values[tax_enabled]" value="0"></section><section class="settings-group"><x-section-heading tag="h3" icon="receipt" tone="info">Printer setup</x-section-heading><x-setting-value label="Printing method" value="Browser print dialog" help="Select the installed printer and its matching 58 mm or 80 mm paper size." /><x-setting-value label="Printer connection" value="No physical printer verified" /><div class="action-row"><a data-modal-link class="button button-secondary" href="{{ route('settings.receipt-preview') }}">Preview saved receipt settings</a></div><p>Printing a preview creates no sale or stock movement. A failed print never requires a second checkout.</p></section>
